encode: state = Σ peg[disk] · 4^disk   (2 bits per disk)
BFS:
  dist[start] = 0
  for each state, for each peg `from` with a top disk d:
      for each peg `to` ≠ from:
          if `to` empty OR top(to) is a LARGER disk:
              relax move to the new state
answer = dist[goal]   # goal = all disks on peg 1 → encoded 0

