public int gena(int n, int[] posts) {
    int start = 0;
    for (int i = 0; i < n; i++) start |= (posts[i] - 1) << (2 * i);
    int total = 1 << (2 * n);
    int[] dist = new int[total];
    java.util.Arrays.fill(dist, -1);
    java.util.ArrayDeque<Integer> q = new java.util.ArrayDeque<>();
    dist[start] = 0;
    q.add(start);
    final int GOAL = 0; // all disks on peg 0 (peg 1)
    while (!q.isEmpty()) {
        int state = q.poll();
        if (state == GOAL) return dist[state];
        int[] top = {-1, -1, -1, -1};
        for (int d = n - 1; d >= 0; d--) {        // large→small: smallest disk wins as top
            int peg = (state >> (2 * d)) & 3;
            top[peg] = d;
        }
        for (int from = 0; from < 4; from++) {
            int d = top[from];
            if (d < 0) continue;
            for (int to = 0; to < 4; to++) {
                if (to == from) continue;
                if (top[to] == -1 || top[to] > d) {  // empty or larger top
                    int next = (state & ~(3 << (2 * d))) | (to << (2 * d));
                    if (dist[next] == -1) {
                        dist[next] = dist[state] + 1;
                        q.add(next);
                    }
                }
            }
        }
    }
    return dist[GOAL];
}

public int genaBidirectional(int n, int[] posts) {
    int start = 0;
    for (int i = 0; i < n; i++) start |= (posts[i] - 1) << (2 * i);
    final int GOAL = 0;
    if (start == GOAL) return 0;
    int total = 1 << (2 * n);
    int[] dF = new int[total]; java.util.Arrays.fill(dF, -1);
    int[] dB = new int[total]; java.util.Arrays.fill(dB, -1);
    java.util.ArrayDeque<Integer> qF = new java.util.ArrayDeque<>();
    java.util.ArrayDeque<Integer> qB = new java.util.ArrayDeque<>();
    dF[start] = 0; qF.add(start);
    dB[GOAL] = 0;  qB.add(GOAL);
    while (!qF.isEmpty() && !qB.isEmpty()) {
        // expand the smaller frontier
        if (qF.size() <= qB.size()) {
            int found = expand(qF, dF, dB, n);
            if (found >= 0) return found;
        } else {
            int found = expand(qB, dB, dF, n);
            if (found >= 0) return found;
        }
    }
    return -1; // unreachable for legal inputs
}

// expands one layer of `q`; returns total distance if it meets the other side, else -1
private int expand(java.util.ArrayDeque<Integer> q, int[] self, int[] other, int n) {
    for (int sz = q.size(); sz > 0; sz--) {
        int state = q.poll();
        int[] top = {-1, -1, -1, -1};
        for (int d = n - 1; d >= 0; d--) top[(state >> (2 * d)) & 3] = d;
        for (int from = 0; from < 4; from++) {
            int d = top[from];
            if (d < 0) continue;
            for (int to = 0; to < 4; to++) {
                if (to == from || !(top[to] == -1 || top[to] > d)) continue;
                int next = (state & ~(3 << (2 * d))) | (to << (2 * d));
                if (self[next] == -1) {
                    self[next] = self[state] + 1;
                    if (other[next] != -1) return self[next] + other[next];
                    q.add(next);
                }
            }
        }
    }
    return -1;
}

