from collections import deque

def gena_bidirectional(self, n: int, posts: list[int]) -> int:
    start = 0
    for i in range(n):
        start |= (posts[i] - 1) << (2 * i)
    GOAL = 0
    if start == GOAL:
        return 0
    total = 1 << (2 * n)
    dF = [-1] * total
    dB = [-1] * total
    dF[start] = 0
    dB[GOAL] = 0
    qF, qB = deque([start]), deque([GOAL])

    def expand(q, self_d, other_d):
        for _ in range(len(q)):
            state = q.popleft()
            top = [-1, -1, -1, -1]
            for d in range(n - 1, -1, -1):
                top[(state >> (2 * d)) & 3] = d
            for frm in range(4):
                d = top[frm]
                if d < 0:
                    continue
                for to in range(4):
                    if to == frm or not (top[to] == -1 or top[to] > d):
                        continue
                    nxt = (state & ~(3 << (2 * d))) | (to << (2 * d))
                    if self_d[nxt] == -1:
                        self_d[nxt] = self_d[state] + 1
                        if other_d[nxt] != -1:
                            return self_d[nxt] + other_d[nxt]
                        q.append(nxt)
        return -1

    while qF and qB:
        if len(qF) <= len(qB):
            found = expand(qF, dF, dB)
        else:
            found = expand(qB, dB, dF)
        if found >= 0:
            return found
    return -1

